     "id": "projected_revenue",
     "type": "predictive",
     "title": "Projected Revenue",
     "formula": "Projected Revenue = Current Revenue × (1 + Growth Rate)<sup>Periods</sup>",
     "interpretation": "Projects future revenue by compounding a current baseline at an assumed growth rate.",
